<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
(() => {
  'use strict';

  /* ======================= UTILITÁRIOS ======================= */
  const UI = { V:'V', R:'Ω', I:'A', P:'W' };
  function escHtml(s){ return String(s?.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c])).replace(/[&<>"']/g,c=>c==='&'?'&amp;':c==='<'?'&lt;':c==='>'?'&gt;':c==='\"'?'&quot;':c==='\''? '&#39;':c); }
  function parseDecimal(s){
    if(!s || s.trim()==='' || Number.isNaN(Number(s.trim()))) return null;
    const n = Number(s.trim().replace(/,/g,'.'));
    return n <= 0 ? null : n;
  }
  function fmtBR(v, dec = 2){
    if(typeof v !== 'number' || !isFinite(v) || v <= 0) return '—';
    if(v === 0) return '0';
    let s = Math.abs(v).toFixed(dec).replace(/\.$/,'');
    const intPart = s.split('.')[0];
    const frac = s.length > 1 ? s.slice(-1).replace(/^\./,'') : '';
    // parte decimal com vírgula; milhar só na parte inteira
    let out = (v < 0 ? '-' : '') + intPart;
    let i = intPart.length;
    while(i > 3){ out += '.'; i -= 3; }
    out += (frac.length > 0 ? ',' + frac : '');
    return out;
  }
  function escala(v){
    if(typeof v !== 'number' || !isFinite(v) || v <= 0) return { vEsc: v, suf:'', mult:1 };
    const mults = { M:1e6, k:1e3, m:1e-3, u:1e-6 };
    let mult, suf = '';
    for(const k of ['M','k','m','u']){ if(Math.abs(v)/mults[k] >= 1 && Math.abs(v)/mults[k] < 1000){ mult = mults[k]; suf = k; break; } }
    const av = mult ? Math.abs(v)/mult : Math.abs(v);
    let s = av.toFixed(2).replace(/\.$/,'').replace(/\.[0]*$/,'');
    const has = s.includes('.' && s.length>1);
    const fp = has ? s.slice(-1) : ''; // último caractere decimal (para decidir vírgula)
    const fracRest = has ? s.slice(s.lastIndexOf('.')) : '';
    const dec = fracRest ? ',' + fracRest.replace(/\./g,'') : '';
    return { vEsc: av, suf: mult ? (' '+suf) : '', dec };
  }
  function showBox(cid, sucesso, dados){
    const alvo = document.getElementById(cid);
    if(!alvo) return;
    const pai = alvo.parentElement;
    pai.innerHTML = '';
    const caixa = document.createElement('div');
    caixa.className = 'result-box anim' + (sucesso ? '' : ' msg-error');
    const icon = sucesso ? '<i class="fas fa-check-circle me-2"></i>' : '<i class="fas fa-exclamation-triangle me-2"></i>';
    let html = '<div class="d-flex flex-column align-items-center gap:.5rem">' +
      '<div class="res-big">' + (dados?.val !== undefined ? dados.val.toFixed(2) : '—') + '</div>' +
      '<span class="res-unit">' + (dados?.unit||'') + '</span></div>' +
      '<div class="res-sub">' +
        (dados?.aviso ? '<p class="text-danger small mb-1">⚠ '+dados.aviso+'</p>' : '') +
        (dados?.eq ? '<p class="fs-6 mb-1">' + dados.eq + '</p>' : '') +
        (dados?.obs ? '<p class="text-muted small mt-1">' + dados.obs + '</p>' : '') +
      '</div>';
    caixa.innerHTML = icon + html;
    pai.appendChild(caixa);
    if(!sucesso){
      caixa.classList.add('msg-shake');
      setTimeout(()=> caixa.classList.remove('msg-shake'), 550);
    }
  }
  function revelar(el){ el.classList.add('in'); }
  function limparMensagens(){
    ['ohm-res','pot-res','res-res','div-res'].forEach(cid=>{
      const p = document.getElementById(cid).parentElement;
      if(p) p.innerHTML = '';
    });
  }
  function montarFormulaPot(opcao, valores){
    const res = resolverOpcaoPot(opcao, valores);
    const exp = EXP_POT[opcao].exp;
    let t = exp.replace(/\s*=\s*/,' = ');
    const re = /\b(V|I|R|P)\b/g;
    t = t.replace(re, (m, letra)=>{
      const v = valores[letra.toLowerCase()];
      if(v===null || !isFinite(v)) return m;
      return fmtBR(v,2) + ' '+UI[letra.toUpperCase()];
    });
    const fim = t.match(/(.*?)\s*=\s*$/);
    if(fim && res!==null && isFinite(res)){
      t = fim[1] + ' = ' + fmtBR(res,2) + ' '+UI[opcao.toUpperCase()];
    }
    return t;
  }
  function resolverOpcaoPot(opcao, valores){
    const V=valores.V||0, R=valores.R||0, I=valores.I||0, P=valores.P||0;
    if(opcao==='P') return (V>0 && I>0) ? V*I : NaN;
    if(opcao==='V') return (P>0 && I>0) ? P/I : (P>0 && R>0) ? P/R : NaN;
    if(opcao==='I') return (P>0 && V>0) ? P/V : (V>0 && R>0) ? V/R : NaN;
    if(opcao==='R') return (V>0 && I>0) ? V/I : (V>0 && P>0) ? V*V/P : NaN;
    return NaN;
  }
  function montarFormulaDiv(valores){
    const t = 'V<sub>o</sub> = V<sub>in</sub> × R<sub>2</sub> ÷ (R<sub>1</sub> + R<sub>2</sub>)';
    t = t.replace(/V<sub>in<\/sub>/g, 'V' + fmtBR(valores.vIn,2) + '<sub>in</sub>');
    t = t.replace(/R<sub>(\d)<\/sub>/g, (m, n) => 'R' + (n==='1'? fmtBR(valores.r1,0) : fmtBR(valores.r2,0)) + ' '+UI.R + '<sub>'+n+'</sub>');
    if(valores.vo !== null && isFinite(valores.vo)){
      t += ' = ' + fmtBR(valores.vo,2) + ' V';
    }
    return t;
  }
  function expressaoOhm(opcao, preen, res){
    const e = { V:'V = R × I', R:'R = V ÷ I', I:'I = V ÷ R' };
    let t = e[opcao].replace(/\s*=\s*/,' = ');
    // substitui R, I, V que aparecerem DEPOIS do "="
    let posIgual = t.indexOf('=');
    if(posIgual === -1) return t;
    const resto = t.slice(posIgual+2).trim().split(/\s+/).filter(Boolean);
    const vars = ['R','I','V'];
    for(let k=0;k<resto.length;k++){
      const tok = resto[k];
      if(tok==='×'){ t = t.slice(0,posIgual+2+k) + ' × ' + t.slice(posIgual+2+k+1); continue; }
      if(tok==='÷'){ t = t.slice(0,posIgual+2+k) + ' ÷ ' + t.slice(posIgual+2+k+1); continue; }
      const chave = tok.toLowerCase();
      if(vars.includes(chave)){
        const vv = preen[chave];
        if(vv !== null && isFinite(vv)){
          const corte = t.indexOf(tok, posIgual+2);
          if(corte > -1){
            const ant = t.slice(0, posIgual+2+corte);
            t = ant + fmtBR(vv) + UI[opcao.toUpperCase()] + t.slice(corte+tok.length+1);
          }
        }
      }
    }
    if(res!==null && isFinite(res)){ t += ' = ' + fmtBR(res,2) + UI[opcao.toUpperCase()]; }
    return t.replace(/\s+$/,'');
  }

  /* ======================= OHM ======================= */
  const STATE_OHM = { V:{hide:['V'], show:['R','I']}, R:{hide:['R'], show:['V','I']}, I:{hide:['I'], show:['V','R'] } };
  function initOhm(){
    const inc = document.getElementById('ohm-inc');
    const map = STATE_OHM[inc.value];
    for(const [chave,{hide,show}] of Object.entries(map)){
      hide.forEach(id=>{ const e = document.getElementById('ohm-'+id); if(e){ e.classList.add('dim'); e.disabled=true; } });
      show.forEach(id=>{ const e = document.getElementById('ohm-'+id); if(e){ e.classList.remove('dim'); e.disabled=false; } });
    }
    document.getElementById('ohm-hint').textContent = 'Preencha os campos disponíveis (os cinzas são opcionais/alternativos). Clique em Calcular para saber o resultado.';
    document.getElementById('ohm-note').textContent = 'As três grandezas estão relacionadas pela fórmula U = R · i. Escolha a incógnita e preencha as outras duas.';
  }
  function calcarOhm(){
    initOhm(); // garante o state correto
    const inc = document.getElementById('ohm-inc').value;
    const casos = {
      V: { need:['R','I'], fn:(r,i)=>(r>0 && i>0)? r*i : NaN,
           aviso:(r,i)=>i===0 ? '⚠ A corrente não pode ser zero — dividir por zero geraria resultado infinito!' : null,
           c:{ e:'V = R × I' }},
      R: { need:['V','I'], fn:(v,i)=>(v>0 && i>0)? v/i : NaN,
           aviso:(v,i)=>i===0 ? '⚠ A corrente não pode ser zero neste cálculo!' : null,
           c:{ e:'R = V ÷ I' }},
      I: { need:['V','R'], fn:(v,r)=>(v>0 && r>0)? v/r : NaN,
           aviso:(v,r)=>r===0 ? '⚠ Resistência zero significa curto-circuito — o resultado não tem significado físico.' : null,
           c:{ e:'I = V ÷ R' }}
    };
    const c = casos[inc];
    const preen = { R: parseDecimal(document.getElementById('ohm-R').value),
                   I: parseDecimal(document.getElementById('ohm-I').value),
                   V: parseDecimal(document.getElementById('ohm-V').value) };
    const faltam = [];
    c.need.forEach(k=>{ if(preen[k]==null) faltam.push(UI[k]); });
    if(faltam.length){
      showBox('ohm-res', false, { aviso:'Ainda faltam valores! Preencha: ' + faltam.join(', ') + '.' });
      return;
    }
    try{
      const res = c.fn(preen.R, preen.I);
      if(!isFinite(res)) throw new Error('Cálculo inválido.');
      const aviso = c.aviso(preen.R, preen.I);
      showBox('ohm-res', true, {
        val: res, unit: UI[inc],
        eq: expressaoOhm(inc, preen, res),
        obs: aviso ? (' '+aviso) : null
      });
    }catch(e){ showBox('ohm-res', false, { aviso:e.message || 'Verifique os valores informados.' }); }
  }
  function limparOhm(){
    limparMensagens();
    document.getElementById('ohm-V').value=''; document.getElementById('ohm-R').value=''; document.getElementById('ohm-I').value='';
    document.querySelectorAll('#ohm-inc option').forEach(o=>o.selected=false);
    document.getElementById('ohm-inc').value='V'; initOhm();
  }

  /* ======================= POTÊNCIA ======================= */
  const PAIRS = {
    P:[
      { active:true,  ordem:['V','I'],  note:'',   cnd:'P = V × I' },
      { active:false, ordem:['V','R'],  note:'Alternativa: P = V² ÷ R', cnd:'P = V² ÷ R' }
    ],
    V:[
      { active:true,  ordem:['P','I'],  note:'',   cnd:'V = P ÷ I' },
      { active:false, ordem:['P','R'],  note:'Alternativa: V = P ÷ R', cnd:'V = P ÷ R' }
    ],
    I:[
      { active:true,  ordem:['P','V'],  note:'',   cnd:'I = P ÷ V' },
      { active:false, ordem:['V','R'],  note:'Alternativa: I = V ÷ R', cnd:'I = V ÷ R' }
    ],
    R:[
      { active:true,  ordem:['V','I'],  note:'',   cnd:'R = V ÷ I' },
      { active:false, ordem:['V','P'],  note:'Alternativa: R = V² ÷ P', cnd:'R = V² ÷ P' }
    ]
  };
  const EXP_POT = { P:{exp:'P = V × I'}, V:{exp:'V = P ÷ I'}, I:{exp:'I = P ÷ V'}, R:{exp:'R = V ÷ I'} };
  function renderPotPares(choice){
    const pairs = PAIRS[choice] || [];
    const cont = document.getElementById('pot-pares');
    if(!cont) return;
    cont.innerHTML = '';
    let cnt = 0;
    pairs.forEach(p => {
