        const s1 = document.createElement('span'); s1.textContent = LABEL_UNIT(p.ordem[0]);
        head.appendChild(b1); head.appendChild(s1);
        const body = document.createElement('div'); body.className = 'pb-body';
        p.ordem.forEach(id => {
          const div = document.createElement('div'); div.className = 'field';
          div.innerHTML = `<label class="form-label small fw-semibold">${LABEL_UNIT(id)}</label>` +
                          `<input type="text" inputmode="decimal" id="pot-${id}-${cnt++}" class="custom-form" autocomplete="off" ${p.active?'':''} spellcheck="false">`;
          body.appendChild(div);
        });
        wrapper.appendChild(head); wrapper.appendChild(body);
      }
      cont.appendChild(wrapper);
    });
    // notas das alternativas
    pairs.forEach(p => { if(p.active === false) cont.appendChild(document.createElement('br'));
                        const np = document.createElement('p'); np.className = 'text-muted small'; np.textContent = p.note; cont.appendChild(np); }) || (() => {});
  }
  function updateHintPot(choice){
    const el = document.getElementById('pot-inc');
    if(!el) return;
    const h = ['Preencha os valores do par indicado. As células cinzas mostram fórmulas alternativas.','Com o valor escolhido, informe qualquer par de grandezas que o sistema descobre o resto.','Preencha potência e tensão, ou potência e resistência.','Preencha tensão e corrente, ou tensão e resistência.'].indexOf(choice);
    document.getElementById('nota-pot').textContent = h>=0 ? 'Preencha o par de valores destacado e clique em Calcular.' : '';
  }
  function calcularPotencia(){
    const choice = document.getElementById('pot-inc').value;
    if(!choice) return;
    const pairs = PAIRS[choice] || [];
    const m = { V: parseDecimal('#pot-V'), I: parseDecimal('#pot-I'), R: parseDecimal('#pot-R'), P: parseDecimal('#pot-P') };
    // correção: ler valores corretamente
    const VG = () => { const e = document.getElementById('pot-V'); return e ? parseDecimal(e.value) : null; };
    const IG = () => { const e = document.getElementById('pot-I'); return e ? parseDecimal(e.value) : null; };
    const RG = () => { const e = document.getElementById('pot-R'); return e ? parseDecimal(e.value) : null; };
    const PG = () => { const e = document.getElementById('pot-P'); return e ? parseDecimal(e.value) : null; };
    let used = null;
    for(const p of pairs){
      const args = [];
      p.ordem.forEach(id=>{ args.push({V:VG(),I:IG(),R:RG(),P:PG()}[id]); });
      if(args.some(a=>a===null)) continue;
      try{
        const res = resolverOpcaoPot(choice, {V:args[0].V, I:args[0].I, R:args[0].R, P:args[0].P});
        if(!isFinite(res)) throw new Error('Verifique os valores.');
        used = { cnd:p.cnd, note:p.note, res };
        let t = EXP_POT[p.key]?.exp ? montagemFallback(p.cnd, {V:args[0].V,I:args[0].I,R:args[0].R,P:args[0].P}) : montarFormulaPot(choice, {V:args[0].V,I:args[0].I,R:args[0].R,P:args[0].P});
        showBox('pot-res', true, { val: res, unit: UI[choice], eq: t, obs: p.note ? (' '+p.note) : null });
        return;
      }catch(e){ /* tenta próximo par */ }
    }
    const missing = [];
    ['V','I','R','P'].forEach(id=>{ const v = [VG,IG,RG,PG][id-1](); if(v===null) missing.push(LABEL_UNIT(id)); });
    showBox('pot-res', false, { aviso:'Combine os valores corretamente! É preciso preencher um par válido: ' + missing.join(', ') + '.' });
  }
  // monta uma expressão coerente com os valores efetivamente informados
  function montagemFallback(cnd, valores){
    const V=valores.V||0, I=valores.I||0, R=valores.R||0, P=valores.P||0;
    let t = cnd.replace(/\s*=\s*/,' = ');
    t = t.replace(/\bV\b/g,(m)=>V>0? fmtBR(V,2)+' '+UI.V : m)
         .replace(/\bI\b/g,(m)=>I>0? fmtBR(I,2)+' '+UI.I : m)
         .replace(/\bR\b/g,(m)=>R>0? fmtBR(R,2)+' '+UI.R : m)
         .replace(/\bP\b/g,(m)=>P>0? fmtBR(P,2)+' '+UI.P : m);
    const fim = t.match(/(.*?)\s*=\s*$/);
    if(fim){ t = fim[1]+' = '+fmtBR(resolvedValueByCnd(cnd,{V:I?null:null,I:I,V:null,P:P})||0,2)+' '+UI[cnd.split(' ')[0].charAt(0).toUpperCase()]; }
    return t;
  }
  // resolve novamente a partir do que foi preenchido (para montar a linha final)
  function resolvedValueByCnd(cnd, vals){
    if(cnd==='P') return vals.V?vals.V*vals.I:null;
    if(cnd==='V') return vals.P? (vals.I?vals.P/vals.I:null) : (vals.P?Math.sqrt(vals.P*vals.R)?null:null : vals.P/vals.R:null);
    if(cnd==='I') return vals.P? (vals.V?vals.P/vals.V:null) : (vals.V?vals.V/vals.R:null);
    if(cnd==='R') return vals.V? (vals.I?vals.V/vals.I:null) : (vals.V?vals.V*vals.V/vals.P:null);
    return null;
  }
  function limparPot(){
    limparMensagens();
    document.querySelectorAll('#pot-V-1,#pot-I-1').forEach(e=>e.value='');
    document.querySelectorAll('[id^=pot-]').forEach(e=>e.value='');
    document.getElementById('pot-inc').value='P'; updateHintPot('P'); renderPotPares('P');
  }

  /* ======================= RESISTORES ======================= */
  let resItems = [];
  const LIMITE = 12;
  let modo = 'paralelo';
  function toggleSerie(){
    const era = modo==='serie';
    modo = era ? 'paralelo' : 'serie';
    document.querySelectorAll('.tg-pill').forEach(b=>{
      b.classList.toggle('active', b.dataset.mode===modo);
    });
    document.body.classList.toggle('active-serie', modo==='serie');
    document.body.classList.remove('active-paralelo-extra');
    if(document.body.classList.contains('active-serie')){
      document.querySelector('.tg-pill.serie').classList.add('active');
      document.querySelector('.tg-pill.paralelo').classList.remove('active');
    }
  }
  function initResistores(){
    const lista = document.getElementById('res-list');
    for(let k=1;k<=3;k++){ addResistor(k); }
    updatePreview();
  }
  function addResistor(idx){
    if(resItems.length >= LIMITE) { alert('Chegamos ao limite de 12 resistores nesta simulação!'); return; }
    const row = document.createElement('div');
    row.className = 'res-row';
    row.dataset.index = resItems.length;
    row.innerHTML = `
      <span class="res-num">${idx}</span>
      <input class="res-val form-control" type="text" inputmode="decimal" data-i="${idx}" placeholder="em Ω (ex.: 100)" spellcheck="false">
      <button class="res-edit" title="Editar valor" type="button" data-idx="${idx}"><i class="fas fa-pencil"></i></button>
      ${resItems.length>0?`<button class="res-del" title="Remover" type="button"><i class="fas fa-trash"></i></button>`:''}
    `;
    const inp = row.querySelector('.res-val');
    const ed = row.querySelector('.res-edit');
    const dl = row.querySelector('.res-del');
    inp.addEventListener('input', () => { updatePreview(); calcularResistores(); });
    ed.addEventListener('click', () => {
      const current = inp.value.trim();
      if(!current) return;
      const nv = prompt('Atualize o valor do resistor R'+idx+' (em Ω):', current);
      if(nv !== null && nv !== '' && isFinite(Number(nv)) && Number(nv)>0){
        inp.value = nv;
      }
    });
    dl.addEventListener('click', () => {
      const idx = parseInt(ed?.dataset?.idx || resItems[resItems.length-1]?.dataset?.index);
      if(idx >= 0){
        const row = document.querySelector('.res-row[data-index="'+idx+'']');
        if(row) row.remove();
        resItems = resItems.filter(r=>r.index !== idx);
      }
      updatePreview(); calcularResistores();
    });
    resItems.push({ index: idx || resItems.length+1, row });
    lista.appendChild(row);
    if(resItems.length > LIMITE) alert('Máximo de resistores atingido.');
  }
  function updatePreview(){
    const todos = resItems.map(r=>({ idx:r.index, val: parseFloat(r.row.querySelector('.res-val').value||'0') })).filter(x=>x.val>0);
    const listOnlyPos = resItems.map(r=>parseFloat(r.row.querySelector('.res-val').value||'0')).filter(x=>x>0);
    let req = null;
    if(todos.length===0){ req=null; }
    else if(todos.length===1){ req = todos[0].val; }
    else if(modo==='serie'){ req = todos.reduce((a,b)=>a.val+b.val,0); }
    else{ req = 1/(todos.reduce((a,b)=>a+1/b.val,0)); }

    const cont = document.getElementById('res-prev');
    if(!cont) return;
    cont.innerHTML = '<div>Req ≈ <b>'+fmtBR(req,3)+'</b> '+UI.R+'</div>';
    const src = parseDecimal('#res-src-v');
    if(src !== null && isFinite(src) && src>0 && req!==null){
      const it = src/req;
      cont.innerHTML += '<div class="text-muted mt-1">Fonte de <b>'+fmtBR(src,2)+'</b> V → corrente total ≈ <b>'+fmtBR(it,3)+'</b> '+UI.I+'</div>';
    }
  }
  function calcularResistores(){
    const todos = resItems.map(r=>({ idx:r.index, val: parseFloat(r.row.querySelector('.res-val').value||'0') })).filter(x=>x.val>0);
    if(todos.length===0){
      showBox('res-res', false, { aviso:'Informe pelo menos 1 resistor com valor > 0 Ω.' });
      return;
    }
    const isSeries = modo==='serie';
    let eq = null;
    try{
      if(isSeries){ eq = todos.reduce((a,b)=>a.val+b.val,0); if(eq<=0) throw new Error('Todos os resistores válidos são de 0 Ω (curto-circuito)!'); }
      else{ const s = todos.reduce((a,b)=>a+1/b.val,0); eq = s===0 ? 0 : 1/s; if(eq<=0) throw new Error('Circuito com curto-circuito (resistência zero em algum ramo)!'); }
    }catch(e){ showBox('res-res', false, { aviso:e.message }); return; }

    const I = (+parseDecimal('#res-src-v')) !== null && isFinite(parseDecimal('#res-src-v')) && +parseDecimal('#res-src-v')>0
                 ? +parseDecimal('#res-src-v')/eq : null;
    const rows = todos.map(r=>{
      const v = isSeries ? I*r.val : (+parseDecimal('#res-src-v'))>0 ? +parseDecimal('#res-src-v') : 0;
      const ic = isSeries ? I : (+parseDecimal('#res-src-v'))>0 ? +parseDecimal('#res-src-v')/r.val : 0;
      const p = Math.max(0, v*ic);
      return { idx:r.idx, R:r.val, V: +(v||0), I: +(ic||0), P: +(p||0) };
    });
    const It = I;
    const Pt = (It!==null && eq!==null) ? eq*I : 0;

    showBox('res-res', true, {
      val: eq, unit: UI.R,
      eq: 'Resistência equivalente = ' + fmtBR(eq,3) + UI.R
    });

    const srcV = +parseDecimal('#res-src-v')||0;
    if(srcV>0 && IsFinite(srcV) && rows.length){
      const box2 = document.getElementById('res-res').parentElement.cloneNode(false);
      // reconstruir card com detalhes
      const card = document.createElement('div');
      card.className = 'result-box anim';
      card.innerHTML =
        '<div class="d-flex flex-column align-items-center gap:.4rem">' +
          '<div class="res-big">Req ≈ <b>'+fmtBR(eq,3)+'</b> Ω</div>' +
          '<div class="text-muted small mt-1">Fonte: <b>'+fmtBR(srcV,2)+'</b> V → Corrente total ≈ <b>'+fmtBR(It!==null?It:'—',3)+'</b> '+UI.I+'</div>' +
        '</div>';
      // tabela
      let th = '<thead class="table-light"><tr><th>Resist.</th><th>Corrente<br>(A)</th><th>Tensão<br>(V)</th><th>Potência<br>(W)</th></tr></thead><tbody>';
      rows.forEach(r=>{
        th += '<tr>'+
          '<td>'+r.idx+' &#9632;<small class="text-muted">'+fmtBR(r.R,0)+'</small></td>'+
          '<td>'+showCell(r.I)+'</td><td>'+showCell(r.V)+'</td><td>'+showCell(r.P)+'</td>'+
        '</tr>';
      });
      const itStr = It !== null ? fmtBR(It,3) : '—';
      const ptStr = Pt !== 0 ? fmtBR(Pt,3) : '—';
      th += '<tr class="tot"><td colspan="2">TOTAL DO CIRCUITO</td><td>—</td><td>It ≈ <b>'+itStr+'</b> ' + (itStr!=='—'?'·':'') +' Pt ≈ <b>'+ptStr+'</b></td></tr></tbody>';
      card.innerHTML += '<table class="res-table">' + th + '</table>' +
        '<p class="text-center text-muted small mt-3">'+notasModo(isSeries)+'</p>';
      const alvo = document.getElementById('res-res').parentElement;
      alvo.innerHTML = '';
      alvo.appendChild(card);
      revelar(card);
    }
  }
  function notasModo(isSeries){
    return isSeries
      ? '<strong>Série:</strong> mesma corrente em todos os resistores; a tensão de cada um é Ui = Ri·i.<br>'+
        '<strong>Paralelo:</strong> todos estão sob a mesma tensão; a corrente de cada ramo é Ii = Vi/Ri.'
      : '<strong>Paralelo:</strong> todos os resistores veem a mesma tensão; a corrente de cada ramo é dividida inversamente à resistência.';
  }
  function showCell(v){ return (v!==null && !isNaN(v)) ? fmtBR(v,3) : '—'; }
  function limparRes(){
    limparMensagens();
    resItems.forEach(r=>{ r.row.querySelectorAll('input').forEach(e=>e.value=''); });
