      '<div class="d-flex flex-column align-items-center gap:.4rem">',
      '<div class="res-big">'+fmtBV(vo)+'</div><span class="res-unit">V</span>',
      '<div class="text-muted small mt-1">Corrente no circuito: <b>'+fmtBR(i,3)+'</b> A · '+
       'R1 dissipa <b>'+fmtBR(pr1,3)+'</b> W · R2 dissipa <b>'+fmtBR(pr2,3)+'</b> W · Total: <b>'+fmtBR(pt,3)+'</b> W</div>',
      '</div>'
    ];
    const grid = infos.map(([titulo,valor,unid])=>{
      const cls = typeof valor === 'number' ? '' : 'text-muted';
      return '<div class="sc '+cls+'"><div class="k">'+escHtml(titulo)+'</div>' +
                                                    '<div class="v">'+fmtBV(valor)+'</div>' +
                                                    '<div class="u">'+escHtml(unid)+'</div></div>';
    }).join('');
    partes.push('<div class="info-grid">'+grid+'</div>',
                '<div class="formula-hl mt-3"><h4>Divisor de Tensão</h4>' +
                '<code>V<sub>o</sub> = V<sub>in</sub> × R<sub>2</sub> ÷ (R<sub>1</sub> + R<sub>2</sub>)</code></div>');
    card.innerHTML = partes.join('');
    b.appendChild(card);
    revelar(card);
  }
  function fmtBV(v){ return isFinite(v)? fmtBR(v,2) : '—'; }

  /* ======================= GUIA ======================= */
  const GUIDE = [
    { icon:'fa-gauge-high', title:'Medindo Corrente', text:'O multímetro deve entrar em SÉRIE no circuito na posição mA/A. Para tensão e resistência, fica em PARALELO. Medir corrente em paralelo queima o instrumento.' },
    { icon:'fa-lightbulb', title:'Dimensionando Resistores', text:'Calcule a potência dissipada (P = V·I) e escolha um resistor com potência ≥ 2× o valor calculado — incluindo margem para temperatura.' },
