  function toggleMenu(){
    const abrir = !document.body.classList.toggle('main-menu-open');
    document.querySelector('.nav-toggle').setAttribute('aria-expanded', String(abrir));
  }
  document.addEventListener('click', e => {
    if(e.target.closest('.nav-toggle') && e.target !== document.querySelector('.nav-toggle')){
      document.body.classList.remove('main-menu-open');
      document.querySelector('.nav-toggle').setAttribute('aria-expanded','false');
    }
  });
  function initScrollSpy(){
    const sec = [...document.querySelectorAll('section.calc-section')];
    const links = [...document.querySelectorAll('.nav-list a[data-target], .m-menu a[data-target]')];
    const io = new IntersectionObserver(entries => {
      let idx = -1;
      for(const e of entries){
        const id = e.target.id;
        idx = sec.findIndex(s => s.id === id);
        if(idx >= 0 && (entries[idx].isIntersecting || (entries[idx].boundingClient && entries[idx].boundingClient.top < 60))){
          destacarNav(idx);
        }
      }
    }, { threshold: [.05,.1,.2,.3,.4,.5] });
    links.forEach(l => {
      const destino = l.getAttribute('data-target');
      l.addEventListener('click', e => { e.preventDefault(); document.getElementById(destino||'#inicio').scrollIntoView({ behavior:'smooth', block:'start' }); });
    });
    sec.forEach(s => io.observe(s));
    destacarNav(0);
  }
  function destacarNav(idx){
    links.forEach(l => {
      const alvo = l.getAttribute('data-target');
      if(alvo && (parseInt(alvo.replace('#','')) === idx || (alvo === '#inicio' && idx === 0))){
        l.classList.toggle('active', idx > 0);
        l.style.borderColor = idx > 0 ? varAccent : 'transparent';
        l.style.backgroundColor = idx > 0 ? 'rgba(37,99,235,.12)' : 'transparent';
        l.style.color = idx > 0 ? '#2563eb' : '#cbd5e1';
      }
    });
  }
  function initReveal(){
    const observaveis = [...document.querySelectorAll('.card-wrap, .guide-item, .hero, .section-head')];
    const io = new IntersectionObserver((e) => {
      for(const item of e){
        if(item.intersects){ item.target.classList.add('in'); io.unobserve(item.target); }
      }
    }, { rootMargin: '0px 0px -50px 0px' });
    observaveis.forEach(x => io.observe(x));
  }

