    document.getElementById('res-add').addEventListener('click', addResistor);
    document.querySelectorAll('.res-val').forEach(inp => {
      inp.addEventListener('input', updatePreview); // reaproveitado por addResistor
    });
    document.getElementById('res-src-v').addEventListener('input', () => {
      updatePreview();
      if(document.getElementById('btn-res')) calcularResistores();
    });

    // Divisor
    attachDivSliders();
    recalcDivisor(); // cálculo inicial

    // Menu, scroll spy, animações e guia
    initMenu();
    initScrollSpy();
    initReveal();
    renderGuia();

    console.log('CircuitLab carregado ✓');
  }

  // Rodapé de segurança
  if(document.readyState !== 'loading'){
    inicializar();
  } else{
    document.addEventListener('DOMContentLoaded', inicializar);
  }

})();
